const open = Temporal.ZonedDateTime.from("2024-10-26T09:00[Europe/London]");
const close = Temporal.ZonedDateTime.from("2024-10-27T09:00[Europe/London]");
const wait = Temporal.Duration.from({ minutes: 150 });

console.log(open.until(close).toString());
console.log(open.until(close, { largestUnit: "days" }).toString());
console.log(wait.round({ smallestUnit: "hours" }).toString());
console.log(wait.round({ smallestUnit: "hours", roundingMode: "floor" }).toString());
